/**
 * The billing lock: a workspace whose subscription is not in good standing is
 * read-only. `lockReasonFor` is the pure rule; `assertWorkspaceWritable` in
 * the billing service loads the subscription and applies it.
 */
import type { Subscription, WorkspaceLockReason } from "@/types/billing";
import type { OrgId } from "@/types/common";

/** Raised by every member write into a locked workspace. */
export class WorkspaceLockedError extends Error {
  readonly code = "plan_limit_exceeded" as const;

  constructor(
    readonly orgId: OrgId,
    readonly reason: WorkspaceLockReason,
  ) {
    super(lockMessage(reason));
    this.name = "WorkspaceLockedError";
  }
}

function lockMessage(reason: WorkspaceLockReason): string {
  switch (reason) {
    case "past_due":
      return "This workspace is read-only because its payment is past due.";
    case "canceled":
      return "This workspace is read-only because its subscription was canceled.";
    case "trial_ended":
      return "This workspace is read-only because its trial has ended.";
  }
}

/** Why the workspace is locked at `now`, or `null` when it is writable. */
export function lockReasonFor(
  subscription: Subscription | null,
  now: Date = new Date(),
): WorkspaceLockReason | null {
  if (!subscription) return null;

  switch (subscription.status) {
    case "active":
      return null;
    case "past_due":
      return "past_due";
    case "trialing":
      return reached(subscription.currentPeriodEnd, now) ? "trial_ended" : null;
    case "canceled":
      if (subscription.cancelAt === null) return "canceled";
      return reached(subscription.cancelAt, now) ? "canceled" : null;
  }
}

function reached(timestamp: string, now: Date): boolean {
  const at = Date.parse(timestamp);
  if (Number.isNaN(at)) return true;
  return now.getTime() >= at;
}
EOF

